 for(const [id,lines] of Object.entries(exchanges)){
  const story=data[id];if(!story)throw Error('Missing comic episode: '+id);
  // Choice stories keep the final decision prompt and all reply/condition data.
  const at=story.lines.length-(story.choice?3:2);
  story.lines.splice(at,2,...lines.map(([who,text,expression])=>L(who,text,expression)));
  story.comicRevision=1;
 }
